<?php

declare(strict_types=1);

use PhpCsFixer\Finder;
use SightPress\Plugin\Core\Quality\CsFixerRules;

require __DIR__.'/vendor/autoload.php';

$finder = Finder::create()
    ->in([__DIR__.'/src', __DIR__.'/config', __DIR__.'/tests', __DIR__.'/quality/src'])
    // Generated by Symfony on every container build.
    ->notPath('Fixtures/App/config/reference.php')
    ->exclude('Quality/Fixtures')
    ->append([__DIR__.'/bin/sightpress-check-budgets']);

return CsFixerRules::config($finder);
